import { useEffect, useRef, useState } from "react";

/**
 * KLoader — Kreethya intro / loading screen.
 *
 * 1. Two plates play a paddle game with a ping-pong ball. The ball is thrown
 *    in, the bottom plate hits it to the left centre, it flies to the top
 *    plate, back to the centre, then down to the bottom plate: the ball's path
 *    draws the two arms of the K, with smoke only where it hits.
 *    Then both plates stand up side by side and become the K's vertical pole.
 *    The ball drops, bounces, and rolls to a stop under the wordmark.
 * 2. The drawn K turns into the Kreethya mark.
 * 3. The wordmark slides in from the right, then the tagline.
 * 4. The screen fades out (or, with the robot, is pulled away like a curtain)
 *    and onFinish() is called: open the home page there.
 *
 * Props
 *   logoSrc    optional. The Kreethya logo is built into this file, so it
 *              always shows. Pass your own transparent 1520 x 378 file to
 *              replace it.
 *   onFinish   called once, after the fade-out.
 *   done       default true. Pass false while your app is still loading: the
 *              finished logo then waits on screen until done becomes true.
 *   progress   optional 0-100, shown as a thin bar while waiting.
 *   fullscreen true (default) covers the viewport; false fills its parent.
 *   alt        accessible name of the logo. Default "Kreethya".
 *   robot      optional ref shared with the page's robot (see Mascot.jsx). When
 *              given, the throw waits (briefly) for robot.current.ready, and
 *              the ball turns into the robot where it lands: the loader writes
 *              robot.current.intro = { x, y, w, stage } in screen pixels, with
 *              stage "in" (tumbling) -> "done" -> "grab": the robot flies to
 *              this screen's left edge and drags it off to the right like a
 *              curtain, writing robot.current.curtainPull = { t0, ms } as it
 *              starts; the screen slides away with its edge in its hands.
 *              If the robot never starts pulling (or did not form), the screen
 *              fades instead and the stage is "fly" (straight to its spot).
 *              If the robot is not ready by then, the ball just rolls as before.
 *   onReveal   called once, as the home page starts to show (pull or fade).
 *
 * Colours come from CSS variables, each with a built-in fallback:
 *   --ground --teal --emerald --lime --smoke --track
 */

// Logo geometry, in pixels of kreethya-logo.png (1520 x 378).
const W = 1520;
const H = 378;
const MARK_END = 438; // the K mark ends here
const WORD_BOTTOM = 298; // the wordmark ends here; the tagline is below
const CHUNKS = [[443, 836], [836, 1323], [1323, 1520]]; // natural gaps in the wordmark
const P = [160, 190]; // where the ball meets the stem
const T = [372, 42]; // top-right corner of the K
const B = [378, 335]; // bottom-right corner of the K
const REACH = 1.6; // the ball flies this much further than the K's corners, so the game is taller
const TP = [P[0] + (T[0] - P[0]) * REACH, P[1] + (T[1] - P[1]) * REACH]; // where the top plate hits it
const BP = [P[0] + (B[0] - P[0]) * REACH, P[1] + (B[1] - P[1]) * REACH]; // where the bottom plate hits it
const E = [1320, -440]; // the ball is thrown in from the upper right (the real start is the top of the screen)
const GROUND = 430; // the floor the ball lands and rolls on, just below the logo
const TAGLINE = ["Powered", "by", "Intelligence.", "Driven", "by", "Possibilities."];
const KEY_WORDS = [2, 5]; // these words get the green shine
const G = [720, BP[1]]; // where the bottom plate catches the ball on the way in
const PAD = { len: 240, th: 34, topY: TP[1] - 57, botY: BP[1] + 57 }; // the two plates, like a paddle game
const DOCK = { x: 62, topY: 100, botY: 280, len: 180, th: 106, time: 0.55 }; // where they stand up to become the pole
const REST_X = 1180; // where the ball rolls to a stop, under the wordmark
// The robot the ball turns into (logo pixels). Its head sits where the ball was.
// tumble: ms the robot takes to form; settle: how long the finished logo holds at least.
// giveUp: ms to wait for the robot to start pulling this screen away before just fading it.
const ROBO = { w: 340, headY: 460, minX: 560, maxX: 1300, tumble: 700, settle: 900, wait: 1500, giveUp: 2500 };
const R = 40; // ball radius
const FALL = 0.7; // seconds from the top of the screen to the ground
const HOP = 0.36; // seconds from the ground to the stem
const HOP_HEIGHT = 60; // extra height of that bounce
const PATH = [[P, TP], [TP, P], [P, BP]];
const SPEED = 2100; // logo pixels per second while the ball is between the plates

const pct = (n) => `${(n * 100).toFixed(2)}%`;
const clip = (x0, x1, y0, y1) => `inset(${pct(y0 / H)} ${pct(1 - x1 / W)} ${pct(1 - y1 / H)} ${pct(x0 / W)})`;

const CSS = `
@import url("https://fonts.googleapis.com/css2?family=Quicksand:wght@500;700&display=swap");
.kl{--kl-ground:var(--ground,#fefefe);--kl-teal:var(--teal,#058875);--kl-emerald:var(--emerald,#02ca96);
--kl-lime:var(--lime,#93dc2c);--kl-ink:var(--ink,#0a392c);--kl-smoke:var(--smoke,#7fa596);--kl-track:var(--track,#e3ece8);
display:grid;place-items:center;overflow:hidden;background:var(--kl-ground);transition:opacity .45s ease}
.kl--full{position:fixed;inset:0;z-index:9999}
.kl--fill{position:relative;width:100%;height:100%;min-height:300px}
.kl--out{opacity:0;pointer-events:none}
.kl--pull{pointer-events:none;--sheer:clamp(0,calc(var(--pull,0) * 5),1);
background:rgba(254,254,254,calc(1 - var(--sheer) * .5));will-change:transform}
.kl--pull::before,.kl--pull::after{content:"";position:absolute;pointer-events:none;opacity:var(--sheer)}
.kl--pull::before{inset:0;background:repeating-linear-gradient(90deg,rgba(255,255,255,.95) 0,rgba(255,255,255,.35) 36px,rgba(232,246,240,.75) 65px,rgba(255,255,255,.3) 96px,rgba(255,255,255,.95) 130px)}
.kl--pull::after{top:0;bottom:0;left:-60%;width:220%;background:linear-gradient(100deg,rgba(255,255,255,0) 38%,rgba(255,255,255,.7) 48%,rgba(220,245,234,.35) 52%,rgba(255,255,255,0) 62%);
animation:kl-silk 1.6s ease-in-out infinite alternate;will-change:transform}
@keyframes kl-silk{0%{transform:translateX(-18%)}100%{transform:translateX(18%)}}
.kl__edge{display:none}
.kl--pull .kl__edge{display:block;position:absolute;top:0;bottom:0;left:0;width:34px;z-index:3;pointer-events:none;
background:linear-gradient(90deg,rgba(255,255,255,1) 0,rgba(214,242,231,.95) 2px,rgba(255,255,255,.9) 5px,rgba(6,42,33,.10) 6px,rgba(6,42,33,0) 34px)}
.kl--pull .kl__logo{opacity:calc(1 - var(--sheer))}
.kl__logo{position:relative;width:min(560px,84vw);aspect-ratio:${W}/${H}}
.kl__logo canvas{position:absolute;inset:-170% -8%;width:116%;height:440%;pointer-events:none}
.kl__logo svg,.kl__logo img{position:absolute;inset:0;width:100%;height:100%;display:block;overflow:visible}
.kl__logo img{opacity:0;user-select:none}
.kl__pad{fill:var(--kl-teal)}
.kl__wall{fill:none;stroke:var(--kl-smoke);stroke-width:3;stroke-dasharray:10 12;opacity:.45}
.kl__streak{stroke:var(--kl-emerald);stroke-width:52;stroke-linecap:round;opacity:.3}
.kl__ring{fill:none;stroke:var(--kl-emerald);stroke-width:5;opacity:0;transform-box:fill-box;transform-origin:center}
.kl__draw{transition:opacity .4s ease}
.kl--logo .kl__draw{opacity:0}
.kl--logo .kl__built{opacity:0}
.kl--logo .kl__ring{animation:kl-ring .8s ease-out}
.kl__mark{transform-origin:14% 50%}
.kl--logo .kl__mark{opacity:1;animation:kl-pop .6s cubic-bezier(.2,.9,.3,1.25)}
.kl__chunk{transform:translateX(14%)}
.kl--logo .kl__chunk{opacity:1;transform:none;transition:opacity .5s ease var(--kl-d),transform .75s cubic-bezier(.16,1,.3,1) var(--kl-d)}
.kl__logo{container-type:inline-size}
.kl__tagline{position:absolute;left:${pct(443 / W)};right:${pct(1 - 1514 / W)};top:78.5%;margin:0;display:flex;justify-content:space-between;white-space:nowrap;
font-family:"Quicksand",system-ui,sans-serif;font-weight:500;font-size:17px;font-size:3.1cqw;line-height:1.2;color:var(--kl-ink)}
.kl__word{display:inline-block;opacity:0}
.kl--logo .kl__word{opacity:1;animation:kl-word .7s cubic-bezier(.16,1,.3,1) var(--kl-d) both}
.kl__word--key{font-weight:700;color:transparent;-webkit-background-clip:text;background-clip:text;background-size:250% 100%;background-position:100% 0;
background-image:linear-gradient(100deg,var(--kl-teal) 0%,var(--kl-emerald) 38%,var(--kl-lime) 50%,var(--kl-emerald) 62%,var(--kl-teal) 100%)}
.kl--logo .kl__word--key{animation:kl-word .7s cubic-bezier(.16,1,.3,1) var(--kl-d) both,kl-shine 1.2s ease-in-out calc(var(--kl-d) + .45s) both}
@keyframes kl-word{0%{opacity:0;transform:translateY(.8em);filter:blur(6px)}100%{opacity:1;transform:none;filter:none}}
@keyframes kl-shine{0%{background-position:100% 0}100%{background-position:0 0}}
.kl__bar{position:absolute;left:50%;top:calc(100% + 32px);width:168px;height:3px;margin-left:-84px;border-radius:2px;background:var(--kl-track);overflow:hidden}
.kl__fill{height:100%;border-radius:2px;background:var(--kl-teal);transition:width .3s ease}
.kl__fill--idle{width:38%;animation:kl-idle 1.25s ease-in-out infinite}
@keyframes kl-pop{0%{transform:scale(1)}40%{transform:scale(1.05)}100%{transform:scale(1)}}
@keyframes kl-ring{0%{opacity:.9;transform:scale(1)}100%{opacity:0;transform:scale(5)}}
@keyframes kl-idle{0%{transform:translateX(-100%)}100%{transform:translateX(265%)}}
@media (prefers-reduced-motion:reduce){.kl,.kl *{animation:none!important;transition:none!important}}
`;

const dist = (a, b) => Math.hypot(b[0] - a[0], b[1] - a[1]);
// Tell the shared robot (see Mascot.jsx) which part of its intro to play.
const easeInOutSine = (k) => -(Math.cos(Math.PI * Math.min(1, Math.max(0, k))) - 1) / 2;
// Tell the robot not to pull this screen (it is fading instead), so it flies straight home.
const skipPull = (robot) => {
  if (robot) robot.current.skipPull = true;
};
const setIntroStage = (robot, stage) => {
  const intro = robot && robot.current.intro;
  if (intro) intro.stage = stage;
};
const rnd = (n) => (Math.random() - 0.5) * n;
const hex = (v, fallback) => {
  const m = /^#?([0-9a-f]{6})$/i.exec((v || "").trim());
  const n = parseInt(m ? m[1] : fallback, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};

export default function KLoader({
  logoSrc = LOGO,
  onFinish,
  done = true,
  progress,
  fullscreen = true,
  alt = "Kreethya",
  robot,
  onReveal,
}) {
  // draw -> logo (mark + wordmark arrive) -> settled -> out -> gone
  const [phase, setPhase] = useState("draw");
  // the ball-to-robot transformation: null -> "in" (tumbling) -> "done"
  const [robo, setRobo] = useState(null);
  // with a robot, the home page waits until the ball has either transformed or come to rest
  const [ballOut, setBallOut] = useState(!robot);
  const rootRef = useRef(null);
  const canvasRef = useRef(null);
  const svgRef = useRef(null);
  const ballRef = useRef(null);
  const spinRef = useRef(null);
  const streakRef = useRef(null);
  const stemRef = useRef(null);
  const topRef = useRef(null);
  const botRef = useRef(null);
  const baseRef = useRef(null);
  const builtRef = useRef(null);
  const padTRef = useRef(null);
  const padBRef = useRef(null);
  const finishRef = useRef(onFinish);
  const revealRef = useRef(onReveal);
  useEffect(() => {
    finishRef.current = onFinish;
    revealRef.current = onReveal;
  });

  const reduced =
    typeof window !== "undefined" &&
    window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // The rally: runs once, never loops.
  useEffect(() => {
    const cvs = canvasRef.current;
    const svg = svgRef.current;
    if (reduced || !cvs || !svg) {
      setPhase("logo");
      return undefined;
    }
    const ctx = cvs.getContext("2d");
    const css = getComputedStyle(rootRef.current);
    const young = hex(css.getPropertyValue("--kl-lime"), "93dc2c");
    const old = hex(css.getPropertyValue("--kl-smoke"), "7fa596");
    let raf = 0;
    let last = performance.now();
    let i = 0; // current leg of PATH
    let d = 0; // distance travelled along it
    let stopped = false;
    let free = null; // the loose ball after the K is finished
    let spin = 0;
    let kick = 0; // stem recoil, 1 -> 0
    let intro = true;
    let tIntro = 0;
    let bounced = false;
    let start = E;
    let px = E[0];
    let py = E[1];
    let parts = [];
    const pads = { t: { x: 780, k: 0 }, b: { x: 1060, k: 0 } }; // plate positions and recoil
    let dock = -1; // -1: plates still playing; 0..1: standing up into the pole
    let morph = -1; // >= 0: seconds since the ball started turning into the robot
    let mx = 0;
    let my = 0;
    let map = { s: 1, ox: 0, oy: 0 };

    const resize = () => {
      if (!rootRef.current) return; // the loader is being removed
      const c = cvs.getBoundingClientRect();
      const g = svg.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      cvs.width = Math.max(1, Math.round(c.width * dpr));
      cvs.height = Math.max(1, Math.round(c.height * dpr));
      map = { s: (g.width / W) * dpr, ox: (g.left - c.left) * dpr, oy: (g.top - c.top) * dpr };
      // start just above the top edge of the screen, wherever the logo sits
      const top = rootRef.current.getBoundingClientRect().top;
      if (tIntro === 0) { start = [E[0], -((g.top - top) / (g.width / W)) - 60]; px = start[0]; py = start[1]; }
    };
    resize();
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
    if (ro) ro.observe(cvs);

    const puff = (x, y, vx, vy, big) => {
      if (parts.length > 420) parts.shift();
      parts.push({
        x: x + rnd(14), y: y + rnd(14), vx, vy, age: 0,
        life: 0.75 + Math.random() * 0.7,
        r0: big ? 30 : 24, r1: (big ? 110 : 84) + Math.random() * 34,
      });
    };
    const burst = (x, y, dirX, n) => {
      for (let k = 0; k < n; k += 1) puff(x, y, dirX * (60 + Math.random() * 220) + rnd(90), rnd(340), true);
    };
    const arm = (el, f) => el && el.setAttribute("stroke-dashoffset", String(1 - f));

    const t0 = performance.now();
    let waiting = !!robot;
    const frame = (now) => {
      if (waiting) {
        // hold the throw (blank screen) until the robot is set up, so it can't stutter later
        if (robot.current.ready || robot.current.failed || now - t0 > ROBO.wait) waiting = false;
        last = now;
        raf = requestAnimationFrame(frame);
        return;
      }
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      let x;
      let y;
      let ux;
      let uy;
      let tail;

      if (intro) {
        // drop from the top, one bounce on the ground, then onto the stem
        tIntro += dt;
        if (tIntro < FALL) {
          const k = tIntro / FALL;
          // a thrown ball: it drifts sideways fast at first, then drops more and more steeply
          x = start[0] + (G[0] - start[0]) * (1 - (1 - k) * (1 - k));
          y = start[1] + (G[1] - start[1]) * (0.25 * k + 0.75 * k * k);
        } else {
          if (!bounced) { bounced = true; pads.b.k = 1; burst(G[0], G[1] + 36, 0, 22); }
          const k = Math.min(1, (tIntro - FALL) / HOP);
          x = G[0] + (P[0] - G[0]) * k;
          y = G[1] + (P[1] - G[1]) * k - 4 * HOP_HEIGHT * k * (1 - k);
          if (k >= 1) { intro = false; kick = 1; burst(P[0] - 10, P[1], 1, 24); }
        }
        const m = Math.hypot(x - px, y - py) || 1;
        ux = (x - px) / m;
        uy = (y - py) / m;
        tail = Math.min(110, (m / dt) * 0.08);
      } else {
        let [from, to] = PATH[i];
        let len = dist(from, to);
        if (!stopped) {
          d += SPEED * dt;
          while (d >= len) {
            if (to === P) { kick = 1; burst(P[0] - 10, P[1], 1, 22); }
            if (i === 0) { arm(topRef.current, 1); arm(baseRef.current, 1); burst(TP[0], TP[1], -0.4, 18); pads.t.k = 1; }
            if (i === PATH.length - 1) {
              arm(botRef.current, 1);
              burst(BP[0], BP[1], -0.2, 20);
              stopped = true;
              free = { x: BP[0], y: BP[1], vx: 620, vy: -420, rolling: false, a: 0 };
              d = len;
              pads.b.k = 1;
              dock = 0; // both plates now leave together to build the pole
              if (streakRef.current) streakRef.current.style.opacity = "0"; // no motion streak once the ball is loose
              break;
            }
            d -= len;
            i += 1;
            [from, to] = PATH[i];
            len = dist(from, to);
          }
        }
        const f = Math.min(1, d / len);
        ux = (to[0] - from[0]) / len;
        uy = (to[1] - from[1]) / len;
        x = from[0] + (to[0] - from[0]) * f;
        y = from[1] + (to[1] - from[1]) * f;
        tail = Math.min(130, d);
        if (!stopped) {
          if (i === 0) { arm(topRef.current, Math.min(1, f * REACH)); arm(baseRef.current, Math.min(1, f * REACH * 1.6)); }
          if (i === 2) arm(botRef.current, Math.min(1, f * REACH));
        }
      }
      px = x;
      py = y;

      if (!stopped) {
        if (ballRef.current) {
          ballRef.current.setAttribute("transform", `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
          ballRef.current.style.opacity = "1";
          spin += 200 * dt; // the light inside the orb swirls slowly while it flies
          if (spinRef.current) spinRef.current.setAttribute("transform", `rotate(${spin.toFixed(1)})`);
        }
        if (streakRef.current) {
          streakRef.current.setAttribute("x1", x); streakRef.current.setAttribute("y1", y);
          streakRef.current.setAttribute("x2", x - ux * tail); streakRef.current.setAttribute("y2", y - uy * tail);
        }
      }
      // the two plates: they follow the ball like a paddle game, then stand up as the pole
      {
        const bx = free ? free.x : x;
        if (dock < 0) {
          const follow = Math.min(1, dt * 13);
          const tt = intro ? Math.max(TP[0] - 120, Math.min(780, bx)) : TP[0];
          const bt = intro && tIntro < FALL ? G[0] : !intro && i === 2 ? BP[0] : Math.max(BP[0] - 130, Math.min(G[0], bx));
          pads.t.x += (tt - pads.t.x) * follow;
          pads.b.x += (bt - pads.b.x) * follow;
        } else if (dock < 1) {
          dock = Math.min(1, dock + dt / DOCK.time);
          if (dock === 1) setPhase("logo");
        }
        const e = dock < 0 ? 0 : dock * dock * (3 - 2 * dock);
        const swap = dock > 0.75 ? (dock - 0.75) / 0.25 : 0; // plates hand over to the logo's own pole
        const draw = (el, p, y0, y1, dir) => {
          if (!el) return;
          p.k = Math.max(0, p.k - dt * 6);
          const len = PAD.len + (DOCK.len - PAD.len) * e;
          const th = PAD.th + (DOCK.th - PAD.th) * e;
          const cx = p.x + (DOCK.x - p.x) * e;
          const cy = y0 + dir * 16 * p.k * (1 - e) + (y1 - y0) * e;
          el.setAttribute("x", String(-len / 2)); el.setAttribute("y", String(-th / 2));
          el.setAttribute("width", String(len)); el.setAttribute("height", String(th));
          el.setAttribute("transform", `translate(${cx.toFixed(1)} ${cy.toFixed(1)}) rotate(${(90 * e).toFixed(1)})`);
          el.style.opacity = String(Math.min(1, tIntro / 0.25) * (1 - swap));
        };
        draw(padTRef.current, pads.t, PAD.topY, DOCK.topY, -1);
        draw(padBRef.current, pads.b, PAD.botY, DOCK.botY, 1);
        if (stemRef.current) stemRef.current.setAttribute("fill-opacity", String(swap));
      }
      if (free) {
        // ordinary ball behaviour: it drops, bounces lower each time, then rolls to a stop
        if (!free.rolling) {
          free.vy += 2600 * dt;
          free.x += free.vx * dt;
          free.y += free.vy * dt;
          if (free.y >= GROUND) {
            free.y = GROUND;
            if (free.vy < 260) {
              free.rolling = true;
              free.a = (free.vx * free.vx) / (2 * Math.max(60, REST_X - free.x));
            } else {
              burst(free.x, GROUND + 36, 0, 5);
              free.vy *= -0.45;
              free.vx *= 0.85;
            }
          }
        } else {
          free.vx = Math.max(0, free.vx - free.a * dt);
          free.x += free.vx * dt;
        }
        if (free.y >= GROUND && robot && robot.current.ready) {
          // transformer moment: the ball bursts open on the floor and the robot tumbles out
          mx = free.x;
          my = free.y;
          morph = 0;
          free = null;
          burst(mx, my, 0, 26);
          burst(mx, my + 30, 0, 10);
          // tell the page's robot where to appear, in screen pixels (its head where the ball was)
          const r = svg.getBoundingClientRect();
          const rx = Math.max(ROBO.minX, Math.min(ROBO.maxX, mx));
          robot.current.intro = {
            stage: "in",
            x: r.left + (rx / W) * r.width,
            y: r.top + (ROBO.headY / H) * r.height,
            w: (ROBO.w / W) * r.width,
          };
          setRobo({ stage: "in" });
        }
      }
      if (free) {
        spin += ((free.vx * dt) / R) * (180 / Math.PI);
        if (ballRef.current) {
          ballRef.current.setAttribute("transform", `translate(${free.x.toFixed(1)} ${free.y.toFixed(1)})`);
          if (spinRef.current) spinRef.current.setAttribute("transform", `rotate(${spin.toFixed(1)})`);
        }
        if (free.rolling && free.vx === 0) {
          free = null;
          setBallOut(true); // came to rest without the robot (it did not load in time)
        }
      }
      if (morph >= 0) {
        // the ball whirls, swells and pops while the robot unfolds from it
        morph += dt;
        const k = Math.min(1, morph / 0.3);
        spin += 1600 * dt;
        const s = (1 + 0.6 * Math.sin(k * Math.PI * 0.8)) * (1 - k * k);
        if (ballRef.current) {
          ballRef.current.setAttribute("transform", `translate(${mx.toFixed(1)} ${my.toFixed(1)}) scale(${Math.max(0.001, s).toFixed(3)})`);
          ballRef.current.style.opacity = String(1 - k * k);
          if (spinRef.current) spinRef.current.setAttribute("transform", `rotate(${spin.toFixed(1)})`);
        }
        if (k >= 1) morph = -2;
      }
      kick = Math.max(0, kick - dt * 5);
      if (builtRef.current) {
        // the K recoils and swells a little on each hit
        const sx = 1 + 0.07 * kick;
        builtRef.current.setAttribute("transform", `translate(${(-10 * kick * kick + 60 * (1 - sx)).toFixed(2)} 0) scale(${sx.toFixed(4)} 1)`);
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, cvs.width, cvs.height);
      ctx.setTransform(map.s, 0, 0, map.s, map.ox, map.oy);
      parts = parts.filter((p) => p.age < p.life);
      for (const p of parts) {
        p.age += dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vx *= 0.96;
        p.vy = p.vy * 0.96 - 46 * dt; // smoke drifts upward
        const k = Math.min(1, p.age / p.life);
        const r = p.r0 + (p.r1 - p.r0) * k;
        const a = 0.55 * (1 - k) * (1 - k);
        const m = Math.min(1, k * 3); // starts lime, cools to grey-green
        const c = young.map((v, n) => Math.round(v + (old[n] - v) * m)).join(",");
        const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
        g.addColorStop(0, `rgba(${c},${a})`);
        g.addColorStop(1, `rgba(${c},0)`);
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
        ctx.fill();
      }

      if (!stopped || free || morph >= 0 || parts.length || dock < 1) raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);

    return () => {
      cancelAnimationFrame(raf);
      if (ro) ro.disconnect();
    };
  }, [reduced, robot]);

  // The robot: tumble out of the ball, then straight off (it says welcome on the page).
  const roboStage = robo && robo.stage;
  useEffect(() => {
    if (roboStage) setIntroStage(robot, roboStage);
    if (roboStage === "in") {
      const t = setTimeout(() => setRobo({ stage: "done" }), ROBO.tumble);
      return () => clearTimeout(t);
    }
    return undefined;
  }, [roboStage, robot]);

  // Logo reveal -> settled -> (when done, and the robot has formed) fade out -> onFinish.
  // With the robot the logo holds only briefly: the robot flying off is the finale.
  const roboBusy = reduced ? false : roboStage === "in" || (!ballOut && roboStage !== "done");
  useEffect(() => {
    if (phase === "logo") {
      const t = setTimeout(() => setPhase("settled"), reduced ? 700 : robot ? ROBO.settle : 3000);
      return () => clearTimeout(t);
    }
    if (phase === "settled" && done && !roboBusy) {
      // a formed robot pulls this screen away like a curtain; otherwise it just fades
      const next = robot && roboStage === "done" && !robot.current.failed ? "pull" : "out";
      const t = setTimeout(() => setPhase(next), 0);
      return () => clearTimeout(t);
    }
    if (phase === "pull") {
      // the robot flies to the left edge, grabs it and drags this screen off to the right,
      // uncovering the home page behind its hands (it writes robot.current.curtainPull)
      setIntroStage(robot, "grab");
      const el = rootRef.current;
      const c = robot.current;
      const t0 = performance.now();
      let raf = 0;
      let started = false;
      const loop = (now) => {
        const pull = c.curtainPull;
        if (!pull && (c.failed || now - t0 > ROBO.giveUp)) {
          skipPull(robot); // the robot never got to it: fade instead
          setPhase("out");
          return;
        }
        if (pull && !started) {
          started = true;
          if (revealRef.current) revealRef.current();
        }
        const q = pull ? easeInOutSine((now - pull.t0) / pull.ms) : 0;
        if (el) {
          el.style.setProperty("--pull", q.toFixed(4));
          // slide the whole screen off to the right (cheap for the graphics card, so it stays smooth)
          el.style.transform = `translate3d(${(q * 100).toFixed(3)}%, 0, 0)`;
        }
        if (q >= 1) {
          setPhase("gone");
          if (finishRef.current) finishRef.current();
          return;
        }
        raf = requestAnimationFrame(loop);
      };
      raf = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(raf);
    }
    if (phase === "out") {
      // the screen fades: the robot (if any) takes off for its spot on the home page
      setIntroStage(robot, "fly");
      if (revealRef.current) revealRef.current();
      const t = setTimeout(() => {
        setPhase("gone");
        if (finishRef.current) finishRef.current();
      }, 480);
      return () => clearTimeout(t);
    }
    return undefined;
  }, [phase, done, reduced, roboBusy, roboStage, robot]);

  if (phase === "gone") return null;

  const shown = phase !== "draw";
  const hasPct = typeof progress === "number" && !Number.isNaN(progress);
  const value = hasPct ? Math.max(0, Math.min(100, Math.round(progress))) : null;
  const showBar = phase !== "out" && phase !== "pull" && (hasPct || !done);
  const cls = `kl ${fullscreen ? "kl--full" : "kl--fill"}${shown ? " kl--logo" : ""}${phase === "out" ? " kl--out" : ""}${phase === "pull" ? " kl--pull" : ""}`;

  return (
    <div ref={rootRef} className={cls} role="status" aria-live="polite" aria-label={shown ? alt : `${alt} is loading`}>
      <style>{CSS}</style>
      {/* the edge the robot holds while it pulls this screen away */}
      <span className="kl__edge" aria-hidden="true" />
      <div className="kl__logo">
        <canvas ref={canvasRef} aria-hidden="true" />
        <svg ref={svgRef} viewBox={`0 0 ${W} ${H}`} aria-hidden="true">
          <defs>
            <clipPath id="kl-orb-clip"><circle r="38" /></clipPath>
            <radialGradient id="kl-orb-glow">
              <stop offset=".55" stopColor="var(--kl-emerald)" stopOpacity=".38" />
              <stop offset="1" stopColor="var(--kl-emerald)" stopOpacity="0" />
            </radialGradient>
            <radialGradient id="kl-orb-body" cx=".42" cy=".38" r=".7">
              <stop offset="0" stopColor="var(--kl-ink)" stopOpacity=".55" />
              <stop offset=".6" stopColor="var(--kl-ink)" stopOpacity=".8" />
              <stop offset="1" stopColor="var(--kl-teal)" stopOpacity=".95" />
            </radialGradient>
            <radialGradient id="kl-orb-shade" cx=".35" cy=".3" r=".8">
              <stop offset="0" stopColor="#fff" stopOpacity=".28" />
              <stop offset=".5" stopColor="#fff" stopOpacity="0" />
              <stop offset="1" stopColor="var(--kl-emerald)" stopOpacity=".45" />
            </radialGradient>
            <clipPath id="kl-c-mark"><rect x="0" y="0" width={MARK_END} height={H} /></clipPath>
            <clipPath id="kl-c-stem"><polygon points="0,0 120,0 120,154 0,299" /></clipPath>
            <clipPath id="kl-c-ribbon"><polygon points="-60,434 470,-17 470,-80 -60,-80" /></clipPath>
            <clipPath id="kl-c-leg"><polygon points="-60,431 470,-20 470,460 -60,460" /></clipPath>
            {/* What the ball has built so far: white areas show the logo's own K. */}
            <mask id="kl-mask" maskUnits="userSpaceOnUse" x="0" y="0" width={W} height={H}>
              <g clipPath="url(#kl-c-mark)" fill="none" stroke="#fff" strokeWidth="200">
                <g clipPath="url(#kl-c-stem)">
                  <rect ref={stemRef} x="0" y="0" width="120" height={H} fill="#fff" fillOpacity="0" stroke="none" />
                </g>
                <g clipPath="url(#kl-c-ribbon)">
                  <path ref={topRef} d="M150 191 L430 -46" pathLength="1" strokeDasharray="1" strokeDashoffset="1" />
                  <path ref={baseRef} d="M150 191 L-30 343" pathLength="1" strokeDasharray="1" strokeDashoffset="1" />
                </g>
                <g clipPath="url(#kl-c-leg)">
                  <path ref={botRef} d="M170 190 L380 410" pathLength="1" strokeDasharray="1" strokeDashoffset="1" />
                </g>
              </g>
            </mask>
          </defs>
          <g className="kl__built">
            <g ref={builtRef}>
              <image href={logoSrc} x="0" y="0" width={W} height={H} mask="url(#kl-mask)" />
            </g>
          </g>
          <g className="kl__draw">
            <rect className="kl__wall" x="10" y="12" width="106" height="356" rx="13" />
            <rect ref={padTRef} className="kl__pad" rx="17" style={{ opacity: 0 }} />
            <rect ref={padBRef} className="kl__pad" rx="17" style={{ opacity: 0 }} />
            <line ref={streakRef} className="kl__streak" x1={E[0]} y1={E[1]} x2={E[0]} y2={E[1]} />
          </g>
          <circle className="kl__ring" cx={B[0]} cy={B[1]} r="42" />
          <g ref={ballRef} transform={`translate(${E[0]} ${E[1]})`} style={{ opacity: 0 }}>
            {/* a glass orb: glow, clear green body, swirling ribbons of light, sparkles, highlights */}
            <circle r="66" fill="url(#kl-orb-glow)" />
            <circle r="40" fill="url(#kl-orb-body)" />
            <g clipPath="url(#kl-orb-clip)">
              <g ref={spinRef}>
                <path d="M-44 6 C-18 -22 14 -20 44 -2 C16 -8 -14 -6 -44 14 Z" fill="var(--kl-lime)" opacity=".75" />
                <path d="M-42 20 C-10 2 20 8 42 22 C14 16 -12 18 -40 30 Z" fill="var(--kl-emerald)" opacity=".8" />
                <path d="M-30 -30 C-6 -16 16 -18 34 -28 C14 -12 -8 -8 -30 -22 Z" fill="var(--kl-teal)" opacity=".55" />
                <circle cx="-10" cy="-4" r="1.8" fill="#fff" />
                <circle cx="8" cy="6" r="1.4" fill="#fff" />
                <circle cx="16" cy="-10" r="1.6" fill="#fff" opacity=".9" />
                <circle cx="-18" cy="12" r="1.3" fill="#fff" opacity=".9" />
                <circle cx="2" cy="-18" r="1.2" fill="#fff" opacity=".8" />
                <circle cx="22" cy="14" r="1.2" fill="#fff" opacity=".8" />
                <circle cx="-4" cy="20" r="1.1" fill="#fff" opacity=".7" />
              </g>
            </g>
            <circle r="40" fill="url(#kl-orb-shade)" />
            <circle r="39" fill="none" stroke="var(--kl-teal)" strokeWidth="2" opacity=".85" />
            <path d="M-30 -14 A33 33 0 0 1 8 -32" fill="none" stroke="#fff" strokeWidth="7" strokeLinecap="round" opacity=".85" />
            <ellipse cx="-17" cy="-21" rx="9" ry="5" transform="rotate(-38 -17 -21)" fill="#fff" opacity=".9" />
            <path d="M14 31 A34 34 0 0 0 31 14" fill="none" stroke="var(--kl-lime)" strokeWidth="4" strokeLinecap="round" opacity=".8" />
          </g>
        </svg>
        <img className="kl__mark" src={logoSrc} alt="" draggable="false" style={{ clipPath: clip(0, MARK_END, 0, H) }} />
        {CHUNKS.map(([x0, x1], n) => (
          <img
            key={x0}
            className="kl__chunk"
            src={logoSrc}
            alt=""
            draggable="false"
            style={{ clipPath: clip(x0, x1, 0, WORD_BOTTOM), "--kl-d": `${0.35 + n * 0.13}s` }}
          />
        ))}
        <p className="kl__tagline" aria-hidden="true">
          {TAGLINE.map((word, n) => (
            <span
              key={n}
              className={`kl__word${KEY_WORDS.includes(n) ? " kl__word--key" : ""}`}
              style={{ "--kl-d": `${1 + n * 0.09}s` }}
            >
              {word}
            </span>
          ))}
        </p>
        {showBar && (
          <div
            className="kl__bar"
            role="progressbar"
            aria-label="Loading"
            aria-valuemin={0}
            aria-valuemax={100}
            {...(value !== null ? { "aria-valuenow": value } : {})}
          >
            <div className={`kl__fill${value === null ? " kl__fill--idle" : ""}`} style={value === null ? undefined : { width: `${value}%` }} />
          </div>
        )}
      </div>
    </div>
  );
}

// The Kreethya logo (transparent WebP), built in so it can never fail to load.
const LOGO =
  "data:image/webp;base64,";
